def main():
    ids = [d["case_id"] for d in DATA]
    assert len(DATA) == 20, f"count={len(DATA)}"
    assert set(ids) == set(EXPECTED), f"id set mismatch: {sorted(set(ids) ^ set(EXPECTED))}"
    assert len(set(ids)) == 20, "duplicate ids"
    for d in DATA:
        assert set(d.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, d["case_id"]
        assert 0.0 <= d["confidence"] <= 1.0, d["case_id"]
        t = d["trigger"]
        assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, d["case_id"]
        assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed")), d["case_id"]
        if d["case_id"].startswith("WP-"):
            assert t == {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}, d["case_id"]
        assert "systems_used" in d["basis"], d["case_id"]
        assert "主线认定" in d["basis"] and "功量清单" in d["basis"], d["case_id"]
    OUT.mkdir(parents=True, exist_ok=True)
    for d in DATA:
        rec = {
            "case_id": d["case_id"],
            "prediction_text": d["prediction_text"],
            "basis": d["basis"],
            "confidence": d["confidence"],
            "trigger": d["trigger"],
        }
        (OUT / f"{d['case_id']}.json").write_text(
            json.dumps(rec, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    ly = [d for d in DATA if d["case_id"].startswith("YM-")]
    counts = {k: sum(1 for d in ly if d["trigger"][k]) for k in ("changed_main", "reserve_used", "disputed")}
    written = [p for p in (f"{i}.json" for i in EXPECTED) if (OUT / p).exists()]
    assert len(written) == 20, f"written={len(written)}"
    print(f"cases={len(DATA)} written={len(written)} liuyao_trigger_counts={counts}")


if __name__ == "__main__":
    main()
